    }

    #[test]
    fn session_epoch_reservation_exceeds_every_durable_generation_after_restart() {
        let (path, journal, config) = epoch_fixture("legacy-restart");
        assert_eq!(journal.reserve_actor_session_epoch(&config, 0).unwrap(), 1);
        journal.critical(|connection| {
            connection.execute_batch(
                "UPDATE printer_actor_state SET session_epoch=31;
                 INSERT INTO ui_event_outbox(stable_id,printer_id,session_epoch,kind,phase,created_at)
                     VALUES('epoch-printer','epoch-printer',48,'connected','ready',1);
                 INSERT INTO command_journal(operation_id,stable_id,session_epoch,method,repeat_policy,priority,state,created_at,updated_at)
                     VALUES('old-command','epoch-printer',51,'server.info','safe','telemetry','confirmed',1,1);
                 INSERT INTO command_journal_archive(operation_id,stable_id,session_epoch,method,repeat_policy,priority,state,attempt_count,created_at,updated_at,deadline_at,archived_at)
                     VALUES('archived-command','epoch-printer',54,'server.info','safe','telemetry','confirmed',1,1,1,2,2);
                 INSERT INTO durable_workflows(workflow_id,operation_id,stable_id,session_epoch,kind,state,deadline_at,idempotency_key,payload_json,created_at,updated_at)
                     VALUES('old-workflow','old-upload','epoch-printer',57,'upload','completed',2,'old-workflow','{}',1,1);"
            ).map_err(|error| error.to_string())
        }).unwrap();
        drop(journal);
        let restarted = Journal::new(&path).unwrap();
        assert_eq!(restarted.reserve_actor_session_epoch(&config, 0).unwrap(), 58);
        assert_eq!(restarted.reserve_actor_session_epoch(&config, 80).unwrap(), 81);
        let persisted: i64 = restarted.read(|connection| connection.query_row(
            "SELECT session_epoch FROM printer_actor_state WHERE stable_id='epoch-printer'", [], |row| row.get(0)
        ).map_err(|error| error.to_string())).unwrap();
        assert_eq!(persisted, 81);
        drop(restarted);
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn session_epoch_reservations_serialize_independent_writers_and_seven_printers() {
        let (path, journal, config) = epoch_fixture("concurrent");
        let barrier = Arc::new(std::sync::Barrier::new(7));
        let threads: Vec<_> = (0..7).map(|_| {
            let writer = Journal::new(&path).unwrap();
            let config = config.clone();
            let barrier = Arc::clone(&barrier);
            std::thread::spawn(move || { barrier.wait(); writer.reserve_actor_session_epoch(&config, 0).unwrap() })
        }).collect();
        let mut epochs: Vec<_> = threads.into_iter().map(|thread| thread.join().unwrap()).collect();
        epochs.sort_unstable();
        assert_eq!(epochs, vec![1, 2, 3, 4, 5, 6, 7]);
        let barrier = Arc::new(std::sync::Barrier::new(7));
        let threads: Vec<_> = (0..7).map(|index| {
            let writer = journal.clone();
            let mut config = config.clone();
            config.stable_id = format!("independent-{index}");
            config.printer_id = config.stable_id.clone();
            let barrier = Arc::clone(&barrier);
            std::thread::spawn(move || { barrier.wait(); writer.reserve_actor_session_epoch(&config, 0).unwrap() })
        }).collect();
        for thread in threads { assert_eq!(thread.join().unwrap(), 1); }
        assert_eq!(journal.reserve_actor_session_epoch(&config, 0).unwrap(), 8);
        drop(journal);
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn session_epoch_reservation_failure_and_exhaustion_never_advance_the_counter() {
        let (path, journal, config) = epoch_fixture("fail-closed");
        assert_eq!(journal.reserve_actor_session_epoch(&config, 0).unwrap(), 1);
        journal.critical(|connection| connection.execute_batch(
            "CREATE TRIGGER reject_session_epoch BEFORE UPDATE OF session_epoch ON printer_actor_state
                 BEGIN SELECT RAISE(ABORT,'injected reservation failure'); END;"
        ).map_err(|error| error.to_string())).unwrap();
        assert!(journal.reserve_actor_session_epoch(&config, 0).unwrap_err().contains("SESSION_EPOCH_RESERVATION_FAILED"));
        journal.critical(|connection| connection.execute_batch("DROP TRIGGER reject_session_epoch;").map_err(|error| error.to_string())).unwrap();
        assert_eq!(journal.reserve_actor_session_epoch(&config, 0).unwrap(), 2);
        for maximum in [MAX_SESSION_EPOCH, u64::MAX] {
            assert!(journal.reserve_actor_session_epoch(&config, maximum).unwrap_err().contains("SESSION_EPOCH_EXHAUSTED"));
        }
        assert_eq!(journal.reserve_actor_session_epoch(&config, 0).unwrap(), 3);
        drop(journal);
        let _ = std::fs::remove_file(path);
    }

