    #[test]
    fn corrupt_command_payload_is_reported_instead_of_skipped() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "klipper-farm-corrupt-journal-{}-{nonce}.sqlite3",
            std::process::id()
        ));
        let mut connection = Connection::open(&path).unwrap();
        super::super::migrations::migrate(&mut connection, 1).unwrap();
        drop(connection);

        let journal = Journal::new(&path).unwrap();
        let request = OperationRequest {
            operation_id: "11111111111111111111111111111111".into(),
            method: "printer.objects.query".into(),
            params: Some(serde_json::json!({"objects":{"print_stats":null}})),
            priority: OperationPriority::Telemetry,
            repeat_policy: RepeatPolicy::Safe,
            prefer_rest: false,
            timeout_ms: 8_000,
            deadline_at_ms: 9_000,
            expected_session_epoch: None,
        };
        journal.create("stable-printer", 1, &request, 1).unwrap();
        journal
            .transition(
                &request.operation_id,
                OperationState::Unknown,
                2,
                None,
                None,
                false,
            )
            .unwrap();
        let operation_id = request.operation_id.clone();
        journal
            .critical(move |connection| {
                connection
                    .execute(
                        "UPDATE command_journal SET params_json='{' WHERE operation_id=?1",
                        params![operation_id],
                    )
                    .map(|_| ())
                    .map_err(|error| error.to_string())
            })
            .unwrap();

        let error = journal
            .recoverable("stable-printer")
            .expect_err("corrupt JSON must fail closed");
        assert!(error.contains("Повреждены параметры command_journal"));

        drop(journal);
        let _ = std::fs::remove_file(&path);
        let _ = std::fs::remove_file(path.with_extension("sqlite3-wal"));
        let _ = std::fs::remove_file(path.with_extension("sqlite3-shm"));
    }

    #[test]
    fn unknown_operation_requires_audited_resolution_before_retention() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "klipper-farm-resolution-journal-{}-{nonce}.sqlite3",
            std::process::id()
        ));
        let mut connection = Connection::open(&path).unwrap();
        super::super::migrations::migrate(&mut connection, 1).unwrap();
        drop(connection);
        let journal = Journal::new(&path).unwrap();
        let request = OperationRequest {
            operation_id: "22222222222222222222222222222222".into(),
            method: "printer.print.start".into(),
            params: Some(serde_json::json!({"filename":"part.gcode"})),
            priority: OperationPriority::Control,
            repeat_policy: RepeatPolicy::Never,
            prefer_rest: false,
            timeout_ms: 8_000,
            deadline_at_ms: 9_000,
            expected_session_epoch: None,
        };
        journal.create("stable-printer", 1, &request, 1).unwrap();
        journal
            .transition(
                &request.operation_id,
                OperationState::Unknown,
                2,
                None,
                Some("result uncertain"),
                true,
            )
            .unwrap();
        assert_eq!(
            journal.list_operations(Some("unknown"), 10).unwrap().len(),
            1
        );
        journal
            .resolve_unknown(
                &request.operation_id,
                "confirmed",
                "operator verified printer state",
                "admin-1",
                3,
            )
            .unwrap();
        let resolved = journal.list_operations(Some("confirmed"), 10).unwrap();
        assert_eq!(resolved.len(), 1);
        assert_eq!(resolved[0].resolution.as_deref(), Some("manual_confirmed"));
        let report = journal
            .housekeeping(100_i64 * 24 * 60 * 60 * 1_000, 90)
            .unwrap();
        assert_eq!(report.archived_commands, 1);
        assert!(journal
            .list_operations(Some("confirmed"), 10)
            .unwrap()
            .is_empty());
        let archived: i64 = journal
            .read(|connection| {
                connection
                    .query_row(
                        "SELECT COUNT(*) FROM command_journal_archive WHERE operation_id=?1",
                        params![request.operation_id],
                        |row| row.get(0),
                    )
                    .map_err(|error| error.to_string())
            })
            .unwrap();
        assert_eq!(archived, 1);
        drop(journal);
        let _ = std::fs::remove_file(&path);
        let _ = std::fs::remove_file(path.with_extension("sqlite3-wal"));
        let _ = std::fs::remove_file(path.with_extension("sqlite3-shm"));
    }
}

