const THEME_STORAGE_KEY='klipper-productivity-theme-v2';
const storedTheme=():ThemeMode=>{try{return localStorage.getItem(THEME_STORAGE_KEY)==='dark'?'dark':'light'}catch{return 'light'}};
const applyTheme=(theme:ThemeMode)=>{
