                `Сохранённый принтер снова найден по новому адресу:\n\n${printerHostDisplay(saved.host)} → ${printerHostDisplay(candidate.host)}\n\nМодель: ${saved.name}\nStable ID: ${stableId}`,
                {title:'Обнаружена смена IP-адреса',confirmLabel:'Обновить адрес',cancelLabel:'Оставить старый'}
              );
              if(!accepted){discoveryRecheckDeclined.current.set(declineKey,Date.now());break}
              const current=printersRef.current.find(printer=>printer.id===saved.id);
              if(!current||samePrinterEndpoint(current.host,candidate.host))break;
              const updated:PrinterModel={...current,host:candidate.host,deviceIdentity:refreshDeviceIdentityEvidence(current.deviceIdentity,detectedIdentity),status:{...current.status,connectionState:'connecting',connectionReason:'connecting',connectionProtocol:probe.protocol,connectionPort:probe.port,connectionMessage:`Адрес обновлён: ${printerHostDisplay(current.host)} → ${printerHostDisplay(candidate.host)}`}};
              const next=printersRef.current.map(printer=>printer.id===saved.id?updated:printer);
