import { PrinterModelPicker } from './PrinterModelPicker';
import catalogStyles from './PrinterModelPicker.module.css';

type ApiKeyValidation={valid:boolean;protocol:'rest'|'websocket';port:number;message:string};

type KnownPreset=Exclude<PrinterProfile['preset'],undefined|'custom'>;
const models:Record<KnownPreset,{name:string;note:string;image:string;camera:string}>={
 'ender3-v3-ke':{name:'Creality Ender-3 V3 KE',note:'220 × 220 × 240 мм',image:printerArtworkByPreset['ender3-v3-ke'],camera:'Камера — только если настроена в Moonraker'},
 'ender3-v3-se':{name:'Creality Ender-3 V3 SE',note:'220 × 220 × 250 мм',image:printerArtworkByPreset['ender3-v3-se'],camera:'Камера — только если настроена в Moonraker'},
 'creality-k1c-2025':{name:'Creality K1C 2025',note:'220 × 220 × 250 мм · закрытая',image:printerArtworkByPreset['creality-k1c-2025'],camera:'Штатная камера Creality + резервный поток'},
 'creality-k1-max':{name:'Creality K1 Max',note:'300 × 300 × 300 мм · закрытая',image:printerArtworkByPreset['creality-k1-max'],camera:'Штатная камера Creality WebRTC'},
 'flashforge-ad5m':{name:FLASHFORGE_5M_DISPLAY_NAME,note:'220 × 220 × 220 мм · открытая',image:printerArtworkByPreset['flashforge-ad5m'],camera:'Штатной камеры нет. Внешняя камера отображается после настройки в Moonraker.'}
};
const fallback=profileForPreset('custom');
const confidenceText=(value?:PrinterDetectionResult['confidence'])=>value==='high'?'высокая':value==='medium'?'средняя':value==='low'?'низкая':'недостаточно данных';
const evidenceLabels:Record<string,string>={
 'identity.exact.ender3-v3-ke':'точное обозначение Ender-3 V3 KE','identity.exact.ender3-v3-se':'точное обозначение Ender-3 V3 SE','identity.exact.creality-k1c':'точное обозначение Creality K1C','identity.exact.creality-k1-max':'точное обозначение Creality K1 Max','identity.exact.flashforge-ad5m':`точное обозначение ${FLASHFORGE_5M_DISPLAY_NAME}`,
 'geometry.220x220x240':'область 220 × 220 × 240','geometry.220x220x250':'область 220 × 220 × 250','geometry.300x300x300':'область 300 × 300 × 300','geometry.220x220x220':'область 220 × 220 × 220','kinematics.cartesian':'кинематика Cartesian','kinematics.corexy':'кинематика CoreXY',
 'levelling.prtouch-v2':'датчик PR Touch V2','levelling.crtouch':'датчик CR/BL Touch','levelling.z-compensation':'компенсация оси Z','board.bl24c16f':'плата BL24C16F',
 'manufacturer.creality':'платформа Creality','manufacturer.flashforge':'платформа FlashForge','firmware.creality-os':'Creality OS','firmware.flashforge-klipper':'FlashForge Klipper','macros.ke-family':'макросы семейства KE','macros.creality-cx-compatible':'совместимый макрос Creality CX','macros.creality-k1-stock':'набор штатных макросов K1','levelling.ad5m-load-cell':'тензодатчик FlashForge','board.ad5m-level-pins':'контур калибровки FlashForge 5M','platform.ad5m-power-pins':'управление питанием FlashForge 5M','platform.ad5m-fan-layout':'вентиляторы платформы FlashForge 5M','geometry.centered-flashforge-220':'центрированная геометрия FlashForge 5M'
};
const evidenceText=(id:string)=>evidenceLabels[id]??id.replace(/[._-]+/g,' ');
const catalogName=(entry:PrinterCatalogModel)=>entry.model.toLocaleLowerCase().startsWith(entry.brand.toLocaleLowerCase())?entry.model:`${entry.brand} ${entry.model}`;

export function PrinterSettings({printer,onSave,onDelete,onClose}:{printer:PrinterModel;onSave:(p:PrinterConfig)=>void|Promise<void>;onDelete:()=>void|Promise<void>;onClose:()=>void}){
 const mounted=useRef(true),draftEpoch=useRef(0),detectionEpoch=useRef(0),detectionRequest=useRef(0);
 const close=()=>{draftEpoch.current+=1;detectionEpoch.current+=1;onClose()};
 useModalAccessibility(close,'.printerSetup',`Настройки ${printer.name}`);
 useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;draftEpoch.current+=1;detectionEpoch.current+=1}},[]);
 const [v,setV]=useState<PrinterModel>({...normalizeCatalogIdentity(printer),profile:{...fallback,...printer.profile},modelSelection:printer.modelSelection??{mode:'manual',selectedPreset:printer.profile?.preset??'custom',source:'legacy'}});
 const updateDraft=(value:Parameters<typeof setV>[0])=>{draftEpoch.current+=1;setV(value)};
 const [saving,setSaving]=useState(false),[detecting,setDetecting]=useState(false),[reattesting,setReattesting]=useState(false),[credentialBusy,setCredentialBusy]=useState(false),[formError,setFormError]=useState(''),[credentialMessage,setCredentialMessage]=useState('');
 const [detectionFresh,setDetectionFresh]=useState(true);
 const p=v.profile!,preset=p.preset??'custom',model=preset!=='custom'?models[preset]:undefined,catalogModel=getCatalogModel(v.catalogModelId);
 const invalidateDetection=()=>{detectionEpoch.current+=1;setDetectionFresh(false);setFormError('')};
 const patch=(x:Partial<PrinterProfile>)=>{invalidateDetection();updateDraft({...v,profile:{...p,...x}})};
 const chooseCatalog=(entry:PrinterCatalogModel|undefined)=>{invalidateDetection();updateDraft(current=>{const next=applyCatalogModel(current,entry);return {...current,...next}})};
 const choose=(value:string)=>{invalidateDetection();const selectedPreset=value as PrinterProfile['preset'];if(selectedPreset==='custom'){updateDraft({...v,profile:{...p,preset:'custom'},modelSelection:{mode:'manual',selectedPreset:'custom',source:'manual',updatedAt:Date.now(),lastDetection:v.modelSelection?.lastDetection}});return}const key=selectedPreset as KnownPreset,selected=models[key],fillName=!catalogModel&&(!v.name.trim()||isAutomaticPrinterName(v));updateDraft({...v,name:fillName?selected.name:v.name,nameSource:fillName?'automatic':v.nameSource,icon:iconForPreset(key),profile:profileForPreset(key),modelSelection:{mode:'manual',selectedPreset:key,source:'manual',updatedAt:Date.now(),lastDetection:v.modelSelection?.lastDetection}})};
 const loadImage=(file?:File)=>{if(!file)return;if(file.size>800_000){setFormError('Изображение должно быть не больше 800 КБ.');return}setFormError('');const reader=new FileReader();reader.onload=()=>updateDraft(x=>({...x,imageData:String(reader.result)}));reader.readAsDataURL(file)};
 const detectModel=async()=>{if(detecting)return;const request=++detectionRequest.current,epoch=detectionEpoch.current,isCurrent=()=>mounted.current&&request===detectionRequest.current&&epoch===detectionEpoch.current;setDetecting(true);setDetectionFresh(false);setFormError('');try{const detected=await new MoonrakerClient(v).detect();if(!isCurrent())return;updateDraft(current=>({...current,...applyModelDetection(current,detected)}));setDetectionFresh(true);if(detected.decision==='probable')setFormError('Модель определена вероятно. Профиль не изменён — подтвердите предполагаемую модель в отчёте ниже.');else if(detected.probeWarnings.length)setFormError(`Модель проверена по неполному снимку: ${detected.probeWarnings.join(', ')}.`)}catch(error){if(isCurrent())setFormError(`Автоопределение не завершено: ${String(error instanceof Error?error.message:error)}`)}finally{if(mounted.current&&request===detectionRequest.current)setDetecting(false)}};
 const confirmProbable=()=>{const report=v.modelSelection?.lastDetection,snapshot=v.configSnapshot;if(!detectionFresh||!report||report.decision!=='probable'||report.model==='custom'||!snapshot)return;const complete:CompleteDetection={...report,facts:snapshot.facts,deviceIdentity:v.deviceIdentity,probeCoverage:snapshot.probeCoverage};updateDraft(current=>({...current,...applyModelDetection(current,complete,true)}));setFormError('Вероятная модель подтверждена пользователем. Профиль будет применён после сохранения настроек.')};
 const reattest=async()=>{if(reattesting)return;setReattesting(true);setFormError('');try{await printerActorReattest(v.id);setFormError('Stable ID и возможности принтера повторно подтверждены Rust Core.')}catch(error){setFormError(`Повторная аттестация не пройдена: ${String(error instanceof Error?error.message:error)}`)}finally{setReattesting(false)}};
 const validateNewKey=async(showSuccess=true)=>{const apiKey=v.apiKey?.trim();if(!apiKey){setCredentialMessage('Введите новый API Key.');return false}setCredentialBusy(true);setCredentialMessage('');try{const result=await secureInvoke<ApiKeyValidation>('validate_moonraker_api_key',{host:v.host,apiKey});if(!result.valid){setCredentialMessage(result.message||'Moonraker отклонил API Key');return false}if(showSuccess)setCredentialMessage(`Ключ подтверждён · ${result.protocol==='websocket'?'WS':'REST'} · ${result.port}`);return true}catch(error){setCredentialMessage(`Проверка ключа не пройдена: ${String(error instanceof Error?error.message:error)}`);return false}finally{setCredentialBusy(false)}};
 const validateSavedKey=async()=>{if(!v.apiKeyStored)return;setCredentialBusy(true);setCredentialMessage('');try{const result=await secureInvoke<ApiKeyValidation>('validate_stored_moonraker_api_key',{printerId:v.id,host:v.host});setCredentialMessage(result.valid?`Сохранённый ключ работает · ${result.protocol==='websocket'?'WS':'REST'} · ${result.port}`:result.message||'Moonraker отклонил сохранённый ключ')}catch(error){setCredentialMessage(`Сохранённый ключ не прошёл проверку: ${String(error instanceof Error?error.message:error)}`)}finally{setCredentialBusy(false)}};
 // Immediate credential deletion must not commit the unsaved catalogue/profile draft.
 const removeSavedKey=async()=>{if(!v.apiKeyStored||credentialBusy)return;const accepted=await appConfirm('Удалить API Key этого принтера из Windows Credential Manager? После удаления Moonraker с авторизацией отключится до ввода нового ключа.',{title:'Удаление API Key',confirmLabel:'Удалить ключ',cancelLabel:'Отмена',danger:true});if(!accepted)return;invalidateDetection();setCredentialBusy(true);setCredentialMessage('');try{await secretDelete(v.id);await onSave({...printer,apiKey:undefined,apiKeyStored:false});updateDraft(current=>({...current,apiKeyStored:false}));setCredentialMessage('API Key удалён из Windows Credential Manager.')}catch(error){setCredentialMessage(`Не удалось удалить ключ: ${String(error instanceof Error?error.message:error)}`)}finally{setCredentialBusy(false)}};
 const save=async()=>{
  if(saving)return;
  const epoch=draftEpoch.current;
  setSaving(true);setFormError('');
  try{
   const keyValid=!v.apiKey?.trim()||await validateNewKey(false);
   if(!mounted.current)return;
   if(epoch!==draftEpoch.current){setFormError('Настройки изменились во время проверки. Нажмите «Сохранить настройки» ещё раз.');return}
   if(!keyValid){setFormError('Новый API Key не сохранён: Moonraker должен подтвердить его до записи.');return}
   await onSave({...v,name:v.name.trim()||(catalogModel?catalogName(catalogModel):model?.name)||'Принтер',icon:iconForPreset(p.preset)});
   if(!mounted.current)return;
   if(epoch!==draftEpoch.current){setFormError('Предыдущие настройки сохранены. Сохраните новые изменения ещё раз.');return}
   close();
  }catch(error){if(mounted.current)setFormError(`Не удалось сохранить: ${String(error instanceof Error?error.message:error)}`)}finally{if(mounted.current)setSaving(false)}
 };
 const storedReport=detectionFresh?v.modelSelection?.lastDetection:undefined,reportTarget=storedReport?.model!=='custom'?storedReport?.model:storedReport?.candidates[0]?.model;
 const report=storedReport?{...storedReport,evidence:storedReport.evidence.filter(item=>!reportTarget||item.model===reportTarget)}:undefined;
 return <div className="modalBackdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="settingsModal printerSetup">
  <div className="panelHead"><div><h2><Printer/> Настройки принтера</h2><p>Выберите модель из каталога и проверьте настройки подключения.</p></div><button className="round" onClick={close}><X/></button></div>
  <div className="printerSetupLayout">
   <aside className="printerSetupPreview"><div className="printerSetupImage">{v.imageData?<img src={v.imageData} alt={v.name}/>:catalogModel?<img src={catalogModelArtwork(catalogModel)} alt={catalogName(catalogModel)}/>:model?<img src={model.image} alt={model.name}/>:<Printer/>}</div><strong>{v.name||(catalogModel?catalogName(catalogModel):model?.name)||'Пользовательский принтер'}</strong><span>{`${p.bedX} × ${p.bedY} × ${p.maxZ} мм · профиль управления`}</span><label className="button"><ImagePlus/> Своя картинка<input hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>loadImage(e.target.files?.[0])}/></label>{v.imageData&&<button className="plainDanger" onClick={()=>updateDraft({...v,imageData:undefined})}>Вернуть изображение модели</button>}</aside>
   <div className="printerSetupContent">
    <section className="setupSection"><header><Printer/><div><h3>Модель из каталога</h3><p>Название модели и изображение. Рабочий профиль сохраняется до отдельной проверки или ручного выбора.</p></div></header><details className={catalogStyles.catalogDetails}><summary>{catalogModel?`Выбрано: ${catalogName(catalogModel)}`:'Выбрать модель из каталога'}</summary><PrinterModelPicker selectedId={v.catalogModelId} onSelect={chooseCatalog} compact/></details></section>
    <section className="setupSection modelDetectionSection"><header><BrainCircuit/><div><h3>Модель и цифровой отпечаток</h3><p>Автоопределение сверяет производителя, платформу, кинематику, геометрию, датчики и макросы — имя принтера не влияет на результат.</p></div><b className={v.modelSelection?.mode==='automatic'?'auto':'manual'}>{v.modelSelection?.mode==='automatic'?'АВТО':'РУЧНОЙ'}</b></header><div className="modelDetectionControls"><details className={catalogStyles.controlDetails}><summary>Профиль управления</summary><label className="field"><span>Рабочий профиль</span><select value={preset} onChange={e=>choose(e.target.value)}>{Object.entries(models).map(([key,x])=><option key={key} value={key}>{x.name}</option>)}<option value="custom">Пользовательский профиль</option></select></label></details><button type="button" disabled={detecting} onClick={detectModel}>{detecting?<LoaderCircle className="spin"/>:<Radar/>}{detecting?'Считываем конфигурацию…':'Определить заново'}</button></div>{report&&<div className={`modelDetectionReport ${report.decision}`}><div><strong>{report.decision==='confirmed'?'Определено точно':report.decision==='probable'?'Вероятная модель — требуется подтверждение':report.decision==='conflict'?(v.modelSelection?.mode==='automatic'?'Противоречие — модельные функции заблокированы':'Признаки не совпали — модель выбрана вручную'):'Модель неизвестна — универсальный профиль'}</strong><span>Уверенность: {confidenceText(report.confidence)} · {report.score} баллов · отрыв {report.margin}</span></div>{report.candidates.length>0&&<div className="modelCandidateList">{report.candidates.slice(0,3).map((candidate,index)=><span key={candidate.model} className={index===0?'leader':''}><b>{models[candidate.model].name}</b><i>{candidate.score}</i></span>)}</div>}{report.evidence.length>0&&<small>{report.evidence.slice(0,4).map(item=>evidenceText(item.id)).join(' · ')}</small>}{report.conflicts.length>0&&<small className="warning"><TriangleAlert/> Конфликт признаков: {report.conflicts.map(item=>item.id.replaceAll('-',' ')).join(', ')}</small>}{report.decision==='probable'&&v.modelSelection?.confirmationRequired&&report.model!=='custom'&&<button type="button" className="primary confirmDetectedModel" onClick={confirmProbable}><Check/>Подтвердить {models[report.model].name}</button>}<em>Отпечаток {report.fingerprint.slice(0,12)} · алгоритм v{report.engineVersion}</em></div>}</section>
    <section className="setupSection"><header><Network/><div><h3>Подключение</h3><p>Адрес Moonraker и ключ доступа с обязательной проверкой.</p></div></header><div className="setupFields two"><label className="field"><span>Название в Klipper Farm</span><input value={v.name} onChange={e=>{updateDraft({...v,name:e.target.value,nameSource:'custom'})}}/></label><label className="field"><span>IP и порт Moonraker</span><input value={v.host} onChange={e=>{invalidateDetection();updateDraft({...v,host:e.target.value});setCredentialMessage('')}}/></label><label className="field wide"><span>Новый API Key</span><input type="password" autoComplete="off" value={v.apiKey??''} onChange={e=>{invalidateDetection();updateDraft({...v,apiKey:e.target.value});setCredentialMessage('')}} placeholder={v.apiKeyStored?'Введите только для замены сохранённого ключа':'Необязательно'}/><small><ShieldCheck/> Хранится только в Windows Credential Manager и не попадает в конфигурацию или журналы.</small></label><div className="apiKeyLifecycle wide"><button type="button" disabled={credentialBusy||!v.apiKey?.trim()} onClick={()=>void validateNewKey()}>{credentialBusy?<LoaderCircle className="spin"/>:<ShieldCheck/>}Проверить новый</button>{v.apiKeyStored&&<button type="button" disabled={credentialBusy} onClick={()=>void validateSavedKey()}>Проверить сохранённый</button>}{v.apiKeyStored&&<button type="button" className="plainDanger" disabled={credentialBusy} onClick={()=>void removeSavedKey()}>Удалить сохранённый</button>}{credentialMessage&&<small>{credentialMessage}</small>}</div></div></section>
    {/карантин|quarant|identity_(?:mismatch|binding)/i.test(v.status.connectionMessage??'')&&<section className="setupSection"><header><TriangleAlert/><div><h3>Quarantine</h3><p>Автоматическая перепривязка запрещена. После проверки адреса запустите управляемую повторную аттестацию.</p></div></header><button type="button" disabled={reattesting} onClick={reattest}>{reattesting?<LoaderCircle className="spin"/>:<ShieldCheck/>}{reattesting?'Проверяем stable ID…':'Повторно подтвердить устройство'}</button></section>}
