import { secureInvoke } from './auth';

export type AuditEntry={id:number;ts:number;user:string;action:string;details:string};
export type AppUser={id:string;name:string;role:'admin'|'operator'|'viewer';enabled:boolean;createdAt:number;pinEnabled:boolean};

export async function dbGet<T>(key:string,fallback:T):Promise<T>{
  try{return await dbGetStrict(key,fallback)}catch{return fallback}
}
// A failed read is not a missing key. Migrations must never replace stored
// data with defaults after a transient SQLite/authentication or JSON error.
export async function dbGetStrict<T>(key:string,fallback:T):Promise<T>{
  const raw=await secureInvoke<string|null>('db_get_json',{key});
  return raw===null?fallback:JSON.parse(raw) as T;
}
export async function dbSet<T>(key:string,value:T){await secureInvoke('db_set_json',{key,value:JSON.stringify(value)})}
export async function migrateLocal<T>(key:string,legacyKeys:string[],fallback:T):Promise<T>{
  const fromDb=await dbGetStrict<T|null>(key,null);
  if(fromDb!==null)return fromDb;
  for(const old of legacyKeys){
    let value:T;
    try{const raw=localStorage.getItem(old);if(raw===null)continue;value=JSON.parse(raw) as T}catch{continue}
    await dbSet(key,value);return value;
  }
  await dbSet(key,fallback);return fallback;
}
export async function audit(action:string,details=''){try{await secureInvoke('audit_add',{action,details});window.dispatchEvent(new Event('klipper-notifications-updated'))}catch{}}
export async function auditList(limit=250){try{return await secureInvoke<AuditEntry[]>('audit_list',{limit})}catch{return []}}
export async function notificationList(limit=100){return await secureInvoke<AuditEntry[]>('notification_list',{limit})}
export async function usersList(){try{return await secureInvoke<AppUser[]>('users_list')}catch{return []}}
export async function userSave(user:AppUser,password?:string,pin?:string,clearPin=false){await secureInvoke('user_save',{user:{...user,password:password||null,pin:pin||null,clearPin}})}
export async function userDelete(id:string){await secureInvoke('user_delete',{id})}
export async function backupJson(){return await secureInvoke<string>('db_backup_json')}
export async function restoreJson(raw:string){return await secureInvoke('db_restore_json',{raw})}

import type { PrinterConfig } from '../types';
import { PRINTER_CATALOG, catalogModelName, getCatalogModel, type PrinterCatalogModel } from './printerCatalog';

const nameKey=(name:string)=>name.normalize('NFKC').toLocaleLowerCase().replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const generatedModelNames=new Set(PRINTER_CATALOG.flatMap(entry=>[catalogModelName(entry),entry.model]).concat([
  'Ender-3 V3 KE','Ender-3 V3 SE','Creality K1C 2025','FlashForge 5M','AD5M',
]).map(nameKey));

// Older releases stored generated model names without recording their origin.
// Match complete model names, never substrings in an operator's own label.
function automaticNameSuffix(config:Pick<PrinterConfig,'name'|'host'|'nameSource'>):string|undefined{
  if(config.nameSource==='custom')return undefined;
  const name=config.name.trim();
  if(generatedModelNames.has(nameKey(name)))return '';
  const numbered=name.match(/^(.+?)\s+(\d{2,})$/);
  if(numbered&&generatedModelNames.has(nameKey(numbered[1])))return ` ${numbered[2]}`;
  if(config.nameSource==='automatic'||!name||name===config.host||/^klipper(?:\s+printer)?(?:\s*[·-]\s*.+)?$/i.test(name)||/^(?:https?:\/\/)?(?:\d{1,3}\.){3}\d{1,3}(?::\d+)?$/i.test(name))return '';
  return undefined;
}

export const isAutomaticPrinterName=(config:Pick<PrinterConfig,'name'|'host'|'nameSource'>)=>automaticNameSuffix(config)!==undefined;

/** Repair the legacy picture/name mismatch without touching a live setup. */
export function normalizeCatalogIdentity<T extends PrinterConfig>(config:T):T{
  const entry=getCatalogModel(config.catalogModelId),suffix=automaticNameSuffix(config);
  if(!entry||suffix===undefined)return config;
  const name=catalogModelName(entry)+suffix;
  return name===config.name?config:{...config,name,nameSource:'automatic'};
}

/**
 * A catalogue identity is separate from the printer's operational profile.
 * Choosing a card does not attest hardware or rewrite a working setup, even
 * when that card has a matching operational preset. Native profiles remain an
 * independent choice and are confirmed by the device probe.
 */
export function applyCatalogModel(config:PrinterConfig,entry?:PrinterCatalogModel):PrinterConfig{
  if(!entry)return {...config,catalogModelId:undefined};
  return normalizeCatalogIdentity({...config,catalogModelId:entry.id});
}

import type { PrinterConfig } from '../types';
import { dbGetStrict, dbSet } from './db';

const CONFIG_KEY='printers.config';
const CACHE_KEY='printers';
const PENDING_KEY='klipper-printers-pending-v1';
type ConfigStorage=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
type PendingConfig={version:1;id:string;configs:PrinterConfig[]};
type StoreDependencies={
  storage?:ConfigStorage;
  read?:()=>Promise<PrinterConfig[]|null>;
  write?:(configs:PrinterConfig[])=>Promise<void>;
};
export type PrinterConfigLoad={configs:PrinterConfig[];needsSave:boolean;pending:boolean};

const parseConfigs=(value:unknown):PrinterConfig[]=>{
  if(!Array.isArray(value)||value.some(item=>!item||typeof item!=='object'||typeof item.id!=='string'||typeof item.name!=='string'||typeof item.host!=='string'))throw new Error('Сохранённые настройки принтеров повреждены. Исходные данные не изменены.');
  return value as PrinterConfig[];
};
export const persistablePrinterConfigs=(configs:PrinterConfig[]):PrinterConfig[]=>parseConfigs(configs).map(value=>{
  const {apiKey,status,webcams,...config}=value as PrinterConfig&{status?:unknown;webcams?:unknown};
  return config;
});

/** Keep the last requested configuration recoverable until SQLite confirms it.
 * The journal contains configuration only; credentials and live telemetry never
 * enter it. Writes are ordered, including retries after a failed write.
 */
export function createPrinterConfigStore(dependencies:StoreDependencies={}){
  const storage=dependencies.storage??localStorage;
  const read=dependencies.read??(()=>dbGetStrict<PrinterConfig[]|null>(CONFIG_KEY,null));
  const write=dependencies.write??(configs=>dbSet(CONFIG_KEY,configs));
  let tail:Promise<unknown>=Promise.resolve();
  const exclusive=<T,>(run:()=>Promise<T>)=>{
    const operation=tail.catch(()=>{}).then(run);
    tail=operation;
    return operation;
  };
  const pending=():PendingConfig|undefined=>{
    const raw=storage.getItem(PENDING_KEY);
    if(raw===null)return;
    const value=JSON.parse(raw) as PendingConfig;
    if(value?.version!==1||typeof value.id!=='string')throw new Error('Не удалось прочитать незавершённое сохранение принтеров. Исходные данные не изменены.');
    return {...value,configs:persistablePrinterConfigs(value.configs)};
  };
  const cached=():PrinterConfig[]=>{
    // A damaged journal is reported by load(), but must not hide an intact
    // last confirmed cache while that error is shown to the user.
    try{const staged=pending();if(staged)return staged.configs}catch{}
    try{
      const raw=storage.getItem(CACHE_KEY);
      return raw===null?[]:persistablePrinterConfigs(parseConfigs(JSON.parse(raw)));
    }catch{return []}
  };
  const finishCache=(staged:PendingConfig)=>{
    // A completed older write must not remove a later request's journal.
    if(pending()?.id!==staged.id)return;
    storage.setItem(CACHE_KEY,JSON.stringify(staged.configs));
    storage.removeItem(PENDING_KEY);
  };
  return{
    cached,
    load({canWrite=true}:{canWrite?:boolean}={}):Promise<PrinterConfigLoad>{
      // Capture before the asynchronous read. A new save queued during this
      // read must keep its own journal and is committed after this operation.
      let staged:PendingConfig|undefined,legacy:PrinterConfig[]|undefined;
      try{
        staged=pending();
        const raw=storage.getItem(CACHE_KEY);
        if(raw!==null)try{legacy=parseConfigs(JSON.parse(raw))}catch{}
      }catch(error){return Promise.reject(error)}
      return exclusive(async()=>{
        const stored=await read();
        if(stored!==null)parseConfigs(stored);
        if(staged){
          if(canWrite){await write(staged.configs);finishCache(staged)}
          return{configs:staged.configs,needsSave:false,pending:!canWrite};
        }
        if(stored!==null){
          if(!pending())storage.setItem(CACHE_KEY,JSON.stringify(persistablePrinterConfigs(stored)));
          return{configs:stored,needsSave:false,pending:false};
        }
        // Legacy credentials are migrated by App before its awaited save.
        // Never write them to the database or the pending journal here.
        return{configs:legacy??[],needsSave:!!legacy,pending:false};
      });
    },
    save(configs:PrinterConfig[]):Promise<void>{
      let staged:PendingConfig;
      try{
        staged={version:1,id:crypto.randomUUID(),configs:persistablePrinterConfigs(configs)};
        storage.setItem(PENDING_KEY,JSON.stringify(staged));
      }catch(error){return Promise.reject(error)}
      return exclusive(async()=>{await write(staged.configs);finishCache(staged)});
    },
  };
}

import type { PrinterConfig, PrinterProfile } from '../types';
import { FLASHFORGE_5M_DISPLAY_NAME } from './printerDetection';
import { printerPresentationPreset } from './printerPresentation';
import { catalogModelName, getCatalogModel } from './printerCatalog';
import { normalizeCatalogIdentity } from './printerCatalogSelection';

const ipLike=/^(?:klipper\s+)?(?:https?:\/\/)?(?:\d{1,3}\.){3}\d{1,3}(?::\d+)?$/i;
const legacyFlashForge5mName=/^(?:(?:flashforge\s+)?(?:adventurer\s+5m|ad5m)|flashforge\s+5m)$/i;

export function normalizePrinterModelDisplayName(value:string|undefined,preset:PrinterProfile['preset']){
  const saved=(value??'').trim();
  if(preset==='flashforge-ad5m'&&(!saved||legacyFlashForge5mName.test(saved)))return FLASHFORGE_5M_DISPLAY_NAME;
  return saved;
}

export function printerDisplayName(printer:PrinterConfig,index=0){
  const saved=normalizePrinterModelDisplayName(normalizeCatalogIdentity(printer).name,printer.profile?.preset);
  const generatedKlipperName=/^klipper(?:\s+printer)?(?:\s*[·-]\s*.+)?$/i.test(saved);
  if(saved&&!generatedKlipperName&&!ipLike.test(saved)&&saved!==printer.host)return saved;
  const catalog=getCatalogModel(printer.catalogModelId);
  if(catalog)return catalogModelName(catalog);
  const preset=printerPresentationPreset(printer);
  if(preset==='ender3-v3-ke')return 'Ender-3 V3 KE';
  if(preset==='ender3-v3-se')return 'Ender-3 V3 SE';
  if(preset==='creality-k1c-2025')return 'Creality K1C 2025';
  if(preset==='creality-k1-max')return 'Creality K1 Max';
  if(preset==='flashforge-ad5m')return FLASHFORGE_5M_DISPLAY_NAME;
  return `Принтер ${String(index+1).padStart(2,'0')}`;
}

export function uniquePrinterName(base:string,existingNames:string[]){
  const clean=base.trim()||'Klipper Printer';
  const used=new Set(existingNames.map(x=>x.trim().toLocaleLowerCase()));
  if(!used.has(clean.toLocaleLowerCase()))return clean;
  let number=2;
  while(used.has(`${clean} ${String(number).padStart(2,'0')}`.toLocaleLowerCase()))number++;
  return `${clean} ${String(number).padStart(2,'0')}`;
}

